import{_ as i,l as o,o as e,c as l,v as r,p as n,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"进位选择","description":"","frontmatter":{"title":"进位选择","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/carry-select.md","filePath":"cs/carry-select.md","lastUpdated":1789023840000}'),E={name:"cs/carry-select.md"};function h(A,a,_,m,u,B){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="进位选择" tabindex="-1">进位选择 <a class="header-anchor" href="#进位选择" aria-label="Permalink to &quot;进位选择&quot;">​</a></h1><div class="epigraph"><p>低位块还在算进位时，高位块先按进位入是 0 和 1 各加一遍，真正的进位到达只选一路。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/ripple-adder">行波进位对照</a>钉死了 RCA 的线性链。<a href="/cs/adder-cla">CLA</a>用 \\(g,p\\) 换深度。本课不重写组生成公式，也不从华莱士树另起。缺口是中间方案：<strong>进位选择</strong>——用面积买掉「等低位进位」的那段空闲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 \\(n\\) 位切成若干块。每块内部仍可用 RCA 或小 CLA。缺口是：块 \\(k\\) 的进位入要等块 \\(k-1\\) 算完。预先做两份：假设进位入为 0 的和与进位出，假设为 1 的另一份；低位进位到达后用 MUX 选。MUX 延迟换成两套加法器。</p><p>块等长时，总延迟大约是一块 RCA 加若干级 MUX，优于纯行波，通常仍不如宽 CLA 树。本课只钉这一种折中。</p><h3 id="选择不是超前" tabindex="-1">选择不是超前 <a class="header-anchor" href="#选择不是超前" aria-label="Permalink to &quot;选择不是超前&quot;">​</a></h3><p>CLA 在进位到达前就用 \\(g,p\\) 组合出正确进位。进位选择是<strong>猜两种、再选</strong>，进位值本身仍来自低位块，只是高位数据和已算好。把 carry-select 叫成 lookahead 的别名，后课分组 CLA 的 \\(G,P\\) 会混。</p><p><span class="marginnote">Harris 用不等长块减小 MUX 链上的空等。本课用等长块讲清结构即可。Patterson/Hennessy 不强制 CPU 用哪一种加法器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>例如 16 位：低 8 位 RCA，高 8 位两套 RCA + 8 位 MUX。进位出同样二选一，接到下一块。关键路径：第一块行波 + 后续 MUX。面积近乎 \\(1.5\\times\\)–\\(2\\times\\) 单套加法器（视块数）。</p>',11)),(e(),n(p,null,{default:t(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LO%5B%22%E4%BD%8E%E4%BD%8D%E5%9D%97%E7%AE%97%E5%87%BA%20c%22%5D%20--%3E%20MUX%5B%22MUX%20%E9%80%89%E9%AB%98%E4%BD%8D%E9%A2%84%E5%8A%A0%E7%BB%93%E6%9E%9C%22%5D%0A%20%20HI0%5B%22%E9%AB%98%E4%BD%8D%E5%81%87%E8%AE%BE%20c%3D0%22%5D%20--%3E%20MUX%0A%20%20HI1%5B%22%E9%AB%98%E4%BD%8D%E5%81%87%E8%AE%BE%20c%3D1%22%5D%20--%3E%20MUX%0A%20%20MUX%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B9%98%E6%B3%95%E9%98%B5%E5%88%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 ALU 仍是一个加减框；框内换 CSA 只改关键路径与面积，控制位不变。与 CLA 可混合：块内 CLA、块间选择。本课不把混合画完。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲进位跳跃（bypass）、不把平方根块长优化写成作业。乘法的部分积压缩是下一课，不是进位选择的推广。</p><p>后课默认：加法器有 RCA / 选择 / CLA 三档延迟–面积；功能都是同一套全加。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进位选择：高位两套预加，低位进位只做 MUX。</li><li>用面积换掉等待，不是 \\(g,p\\) 超前。</li><li>控制与溢出接线与上一课相同。</li><li>出处：Harris and Harris。</li></ul>',7))])}const f=i(E,[["render",h]]);export{D as __pageData,f as default};
